const decoder = new SSEDecoder();

// Test 1: Fragmented chunk parsing
const chunk1 = "data: first line\n";
const chunk2 = "data: second line\nevent: custom\nid: evt_1\n\n";

const res1 = decoder.push(chunk1);
console.assert(res1.length === 0, "Expected 0 events for incomplete chunk");

const res2 = decoder.push(chunk2);
console.assert(res2.length === 1, "Expected 1 event");
console.assert(res2[0].event === "custom", `Expected custom event, got ${res2[0].event}`);
console.assert(res2[0].data === "first line\nsecond line", `Expected multi-line data, got ${res2[0].data}`);
console.assert(res2[0].id === "evt_1", `Expected id evt_1, got ${res2[0].id}`);

console.log("TypeScript SSEDecoder Test Passed! 100% assertions satisfied.");
